"""
test_migrations.py

The migrations are the schema. These tests fail when models.py and the
Alembic revisions disagree, when two revisions claim the same parent, or
when a revision cannot be undone and applied again.
"""

from alembic import command
from alembic.script import ScriptDirectory

import database


def test_models_match_migrations(alembic_config):
    # Same as `alembic check`: raises AutogenerateDiffsDetected on any drift
    command.check(alembic_config)


def test_single_head(alembic_config):
    heads = ScriptDirectory.from_config(alembic_config).get_heads()
    assert len(heads) == 1, f"Several migration heads, merge them: {heads}"


def test_downgrade_then_upgrade(alembic_config):
    # No db_session here, and no pooled connection left open: a session
    # holding a lock on a table would make the DROP wait forever.
    database.engine.dispose()
    command.downgrade(alembic_config, "base")
    command.upgrade(alembic_config, "head")
    command.check(alembic_config)
